export interface ApiResponse<T> {
  data: T;
  success: boolean;
  message?: string;
}

// 통일된 API 응답 형식 (성공)
export interface SuccessApiResponse<T> {
  success: true;
  message?: string;
  data: T;
}

// 통일된 API 응답 형식 (에러)
export interface ErrorApiResponse {
  success: false;
  error: string;
  code?: string;
  message?: string;
}

// 통일된 API 응답 형식 (성공 또는 에러)
export type UnifiedApiResponse<T> = SuccessApiResponse<T> | ErrorApiResponse;

