// 브로커 목록 상수
export const BROKERS: Broker[] = [
  { id: 'dongjin.lee', name: '동진' },
  { id: 'donggyu.lee', name: '동규' },
  { id: 'sp6218', name: '최진석' }
];

// 브로커 ID로 이름 찾기 유틸리티
export const getBrokerName = (brokerId: string): string => {
  const broker = BROKERS.find(b => b.id === brokerId);
  return broker ? broker.name : brokerId;
};

