// Stay 검색 및 주문 주소 변경 관련 API 함수
import { 
  StaySearchRequest, 
  StaySearchResponse, 
  UpdateOrderAddressRequest, 
  UpdateOrderAddressResponse,
  ErrorApiResponse
} from '../types';

// 환경에 따른 API URL 설정
const getApiBaseUrl = () => {
  // 개발 환경
  if (process.env.NODE_ENV === 'development') {
    return process.env.REACT_APP_API_URL || 'http://localhost:8084';
  }
  
  // 운영 환경 - 기본값으로 운영 API 서버 사용
  return process.env.REACT_APP_API_URL || 'https://api.brainbackdoor.com';
};

const API_BASE_URL = getApiBaseUrl();

// 공통 헤더
const getHeaders = () => ({
  'Content-Type': 'application/json',
  'Accept': 'application/json',
  'X-SERVER-AUTH': 'secret',
});

// 공통 에러 처리
const handleResponseError = async (response: Response): Promise<never> => {
  if (response.status === 401) {
    throw new Error('인증에 실패했습니다. 관리자에게 문의하세요.');
  } else if (response.status === 403) {
    throw new Error('접근이 거부되었습니다. API 키를 확인해주세요.');
  } else if (response.status === 404) {
    throw new Error('요청한 리소스를 찾을 수 없습니다.');
  } else if (response.status === 400) {
    // 400 에러의 경우 서버 응답에서 에러 메시지 추출 시도
    try {
      const errorData: ErrorApiResponse = await response.json();
      throw new Error(errorData.error || errorData.message || '잘못된 요청입니다. 입력값을 확인해주세요.');
    } catch (parseError) {
      throw new Error('잘못된 요청입니다. 입력값을 확인해주세요.');
    }
  } else if (response.status >= 500) {
    throw new Error('서버에 문제가 발생했습니다. 잠시 후 다시 시도해주세요.');
  } else {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
};

// 네트워크 에러 처리
const handleNetworkError = (error: unknown): never => {
  if (error instanceof TypeError && error.message.includes('fetch')) {
    throw new Error('API 서버에 연결할 수 없습니다. 네트워크 연결을 확인하거나 관리자에게 문의하세요.');
  }
  throw error;
};

// Stay 검색 API
export const searchStaysByAddress = async (
  request: StaySearchRequest
): Promise<StaySearchResponse> => {
  const url = `${API_BASE_URL}/api/hosts/stays/search-by-address`;
  
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: getHeaders(),
      mode: 'cors',
      body: JSON.stringify({
        address: request.address,
        detailAddress: request.detailAddress || null
      }),
    });

    if (!response.ok) {
      await handleResponseError(response);
    }

    const data: any = await response.json();
    
    // 응답 형식 검증
    // 백엔드가 통일된 형식을 적용했다면 success 필드가 있음
    if ('success' in data) {
      // 통일된 형식 사용 중
      if (!data.success) {
        const errorData = data as ErrorApiResponse;
        throw new Error(errorData.error || errorData.message || 'Stay 검색에 실패했습니다.');
      }
      // success가 true이면 성공
      return data as StaySearchResponse;
    } else {
      // 통일된 형식이 아직 적용되지 않음 - HTTP 상태 코드로 판단
      // response.ok가 true이면 성공으로 간주하고 통일된 형식으로 래핑
      return {
        success: true,
        data: Array.isArray(data) ? data : (data.data || []),
      } as StaySearchResponse;
    }
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

// 주문 주소 변경 API
export const updateOrderAddress = async (
  orderId: string,
  request: UpdateOrderAddressRequest
): Promise<UpdateOrderAddressResponse> => {
  const url = `${API_BASE_URL}/api/orders/${orderId}/address`;
  
  try {
    const response = await fetch(url, {
      method: 'PUT',
      headers: getHeaders(),
      mode: 'cors',
      body: JSON.stringify({
        stayId: request.stayId
      }),
    });

    if (!response.ok) {
      await handleResponseError(response);
    }

    const data: any = await response.json();
    
    // 응답 형식 검증
    // 백엔드가 통일된 형식을 적용했다면 success 필드가 있음
    // 아직 적용하지 않았다면 HTTP 상태 코드만으로 판단 (200 OK면 성공)
    if ('success' in data) {
      // 통일된 형식 사용 중
      if (!data.success) {
        const errorData = data as ErrorApiResponse;
        throw new Error(errorData.error || errorData.message || '주소 변경에 실패했습니다.');
      }
      // success가 true이면 성공
      return data as UpdateOrderAddressResponse;
    } else {
      // 통일된 형식이 아직 적용되지 않음 - HTTP 상태 코드로 판단
      // response.ok가 true이면 성공으로 간주하고 통일된 형식으로 래핑
      return {
        success: true,
        data: data,
      } as UpdateOrderAddressResponse;
    }
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};
