/** Host 신청 관리 API (member `/api/host-applications`) */

export type HostApplicationStatus = 'PENDING' | 'APPROVED' | 'REJECTED';

export type HostApplicationQrStatus = 'NOT_STARTED' | 'QR_GENERATED' | 'QR_SENT';

export interface LinkedStaySummary {
  stay_id: string;
  stay_name: string;
  display_line: string;
  /** 목록 필터 등 — API 미제공 시 생략될 수 있음 */
  active?: boolean | null;
}

export interface FieldError {
  field: string;
  message: string;
}

export interface ApiResponse<T> {
  success: boolean;
  message: string;
  data: T;
  errors?: FieldError[];
  code?: string;
}

export interface StateConflictBody {
  currentStatus: HostApplicationStatus;
  current_qr_status?: HostApplicationQrStatus;
}

export interface ResultView {
  success: false;
  message: string;
  body?: string;
}

export interface AdminResponse {
  id: string;
  name: string;
  phone: string;
  address: string;
  entrancePassword: string;
  receiveMethod: string;
  receiveAddressChange: string | null;
  businessType: string;
  operationType: string[];
  operationStatus: string;
  referralSource: string[];
  referrerName: string | null;
  shippingConfirm: boolean;
  status: HostApplicationStatus;
  rejectionReason: string | null;
  hostId: string | null;
  linked_stay_id: string | null;
  /** 목록/상세 확장 — 구버전 API에서는 생략될 수 있음 */
  linked_stay?: LinkedStaySummary | null;
  duplicate_stay_name?: boolean;
  qr_status?: HostApplicationQrStatus;
  createdAt: string;
  approvedAt: string | null;
  rejectedAt: string | null;
}

/** 본문 포함 승인 — POST /api/stays Stay 필드와 동일 의미 */
export interface ApproveRequest {
  address: string;
  lat: number;
  lng: number;
  stay_name: string;
  detail_address?: string | null;
  note?: string | null;
  display_info?: string | null;
}

export interface RejectRequest {
  reason: string;
}

export const HOST_APPLICATION_CODES = {
  VALIDATION_FAILED: 'HOST_APPLICATION_VALIDATION_FAILED',
  ALREADY_APPROVED: 'HOST_APPLICATION_ALREADY_APPROVED',
  ALREADY_REJECTED: 'HOST_APPLICATION_ALREADY_REJECTED',
  NOT_APPROVED: 'HOST_APPLICATION_NOT_APPROVED',
  QR_REQUIRES_LINKED_STAY: 'HOST_APPLICATION_QR_REQUIRES_LINKED_STAY',
  QR_INVALID_TRANSITION: 'HOST_APPLICATION_QR_INVALID_TRANSITION',
} as const;

export interface HostApplicationListParams {
  status?: string;
  qr_status?: string;
  limit?: number;
  cursor?: string;
}

export interface HostApplicationListResult {
  items: AdminResponse[];
  hasMore: boolean;
  nextCursor: string | null;
}
