import React, { useCallback, useEffect, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import MapComparison from '../components/Maps/MapComparison';
import NaverMapComponent from '../components/Maps/NaverMapComponent';
import GoogleMapComponent from '../components/Maps/GoogleMapComponent';
import {
  translateAddress,
  getGoogleGeocode,
  generateStayName,
} from '../utils/stayApi';
import {
  approveHostApplication,
  getHostApplication,
  HostApplicationApiError,
} from '../utils/hostApplicationApi';
import { AdminResponse, HOST_APPLICATION_CODES } from '../types/hostApplication';
import { useToast } from '../hooks/useToast';
import { stripRepublicOfKoreaSuffix } from '../utils/addressFormat';

type Step = 'input' | 'map' | 'address-correction' | 'stay-fields' | 'success';

interface TranslationResult {
  englishAddress: string;
  englishDetailAddress: string;
  lat: number;
  lng: number;
}

const HostApplicationCompletePage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { showToast } = useToast();

  const [application, setApplication] = useState<AdminResponse | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [initialLoading, setInitialLoading] = useState(true);

  const [currentStep, setCurrentStep] = useState<Step>('input');
  const [isLoading, setIsLoading] = useState(false);

  const [koreanAddress, setKoreanAddress] = useState('');
  const [translationResult, setTranslationResult] = useState<TranslationResult | null>(null);
  const [isCorrection, setIsCorrection] = useState(false);
  const [correctionAddress, setCorrectionAddress] = useState('');
  const [correctionTranslationResult, setCorrectionTranslationResult] =
    useState<TranslationResult | null>(null);

  const [stayName, setStayName] = useState('');
  const [stayNote, setStayNote] = useState('');
  const [displayInfo, setDisplayInfo] = useState('');
  const [addressConfirmed, setAddressConfirmed] = useState(false);

  const [successData, setSuccessData] = useState<AdminResponse | null>(null);

  const loadApplication = useCallback(async () => {
    if (!id) return;
    setInitialLoading(true);
    setLoadError(null);
    try {
      const data = await getHostApplication(id);
      if (data.status !== 'PENDING' && data.status !== 'REJECTED') {
        setLoadError('이미 처리된 신청입니다. 온보딩 승인을 진행할 수 없습니다.');
        setApplication(data);
      } else {
        setApplication(data);
        setKoreanAddress(data.address);
        setStayName(generateStayName(data.address));
      }
    } catch (e) {
      const msg =
        e instanceof HostApplicationApiError
          ? e.message
          : e instanceof Error
            ? e.message
            : '신청을 불러오지 못했습니다.';
      setLoadError(msg);
      setApplication(null);
    } finally {
      setInitialLoading(false);
    }
  }, [id]);

  useEffect(() => {
    void loadApplication();
  }, [loadApplication]);

  useEffect(() => {
    const translateCorrectionAddress = async () => {
      if (!correctionAddress.trim()) {
        setCorrectionTranslationResult(null);
        return;
      }
      try {
        const tr = await translateAddress({ address: correctionAddress });
        const geo = await getGoogleGeocode(tr.englishAddress);
        setCorrectionTranslationResult({
          englishAddress: stripRepublicOfKoreaSuffix(tr.englishAddress),
          englishDetailAddress: tr.englishDetailAddress,
          lat: geo.lat,
          lng: geo.lng,
        });
      } catch {
        setCorrectionTranslationResult(null);
      }
    };
    const timeoutId = setTimeout(translateCorrectionAddress, 300);
    return () => clearTimeout(timeoutId);
  }, [correctionAddress]);

  const handleInputSubmit = async () => {
    if (!koreanAddress.trim()) {
      showToast('주소를 입력해주세요.', 'error');
      return;
    }
    setIsLoading(true);
    try {
      const tr = await translateAddress({ address: koreanAddress });
      const geo = await getGoogleGeocode(tr.englishAddress);
      setTranslationResult({
        englishAddress: stripRepublicOfKoreaSuffix(tr.englishAddress),
        englishDetailAddress: tr.englishDetailAddress,
        lat: geo.lat,
        lng: geo.lng,
      });
      setCurrentStep('map');
    } catch (e) {
      showToast(e instanceof Error ? e.message : '처리 중 오류가 발생했습니다.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const handleLocationCorrect = () => {
    setIsCorrection(false);
    setCorrectionAddress('');
    setCorrectionTranslationResult(null);
    if (translationResult) {
      setDisplayInfo((prev) =>
        prev.trim() ? prev : translationResult.englishAddress
      );
    }
    setCurrentStep('stay-fields');
    showToast('위치 확인이 완료되었습니다.', 'success');
  };

  const handleLocationIncorrect = () => {
    setIsCorrection(true);
    setCurrentStep('address-correction');
  };

  const handleAddressCorrectionConfirm = () => {
    if (!correctionTranslationResult) return;
    setDisplayInfo((prev) =>
      prev.trim() ? prev : correctionTranslationResult.englishAddress
    );
    setCurrentStep('stay-fields');
    showToast('주소 보정이 반영되었습니다.', 'success');
  };

  const finalTranslation = (): TranslationResult | null => {
    if (correctionTranslationResult) return correctionTranslationResult;
    return translationResult;
  };

  const handleApproveSubmit = async () => {
    if (!id || !application) return;
    const ft = finalTranslation();
    if (!ft) {
      showToast('주소·좌표 정보가 없습니다. 이전 단계를 다시 진행해주세요.', 'error');
      return;
    }
    if (!stayName.trim()) {
      showToast('스테이 이름을 입력해주세요.', 'error');
      return;
    }
    if (!addressConfirmed) {
      showToast('지도에서 주소를 확인했음을 체크해주세요.', 'error');
      return;
    }

    const body: Parameters<typeof approveHostApplication>[1] = {
      address: stripRepublicOfKoreaSuffix(ft.englishAddress.trim()),
      lat: ft.lat,
      lng: ft.lng,
      stay_name: stayName.trim(),
    };
    const det = ft.englishDetailAddress?.trim();
    if (det) body.detail_address = det;
    const n = stayNote.trim();
    if (n) body.note = n;
    // Stay 추가와 동일: display_info 기본값은 영문 주소(번역 결과), ROK 접미사 제거
    body.display_info = stripRepublicOfKoreaSuffix(
      (displayInfo.trim() || ft.englishAddress).trim()
    );

    setIsLoading(true);
    try {
      const data = await approveHostApplication(id, body);
      setSuccessData(data);
      setCurrentStep('success');
      showToast('승인이 완료되었습니다.', 'success');
    } catch (e) {
      if (e instanceof HostApplicationApiError) {
        if (e.code === HOST_APPLICATION_CODES.ALREADY_APPROVED) {
          showToast('이미 승인된 신청입니다.', 'error');
          navigate(`/host-applications/${id}`);
          return;
        }
        if (e.fieldErrors?.length) {
          showToast(e.fieldErrors.map((x) => x.message).join(' '), 'error');
        } else {
          showToast(e.message, 'error');
        }
      } else {
        showToast('승인 요청에 실패했습니다.', 'error');
      }
    } finally {
      setIsLoading(false);
    }
  };

  if (!id) {
    return <div className="p-8 text-center text-gray-600">잘못된 경로입니다.</div>;
  }

  if (initialLoading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center text-gray-500">
        불러오는 중…
      </div>
    );
  }

  if (loadError || !application) {
    return (
      <div className="min-h-screen bg-gray-50 p-8 text-center space-y-4">
        <p className="text-gray-700">{loadError ?? '신청을 찾을 수 없습니다.'}</p>
        <Link to="/host-applications" className="text-blue-600 hover:underline">
          목록으로
        </Link>
      </div>
    );
  }

  if (application.status !== 'PENDING' && application.status !== 'REJECTED') {
    return (
      <div className="min-h-screen bg-gray-50 p-8 text-center space-y-4">
        <p className="text-gray-700">온보딩 승인을 진행할 수 있는 상태가 아닙니다.</p>
        <Link
          to={`/host-applications/${id}`}
          className="text-blue-600 hover:underline"
        >
          상세로
        </Link>
      </div>
    );
  }

  const renderInputStep = () => (
    <div className="max-w-2xl mx-auto">
      <div className="bg-white rounded-lg shadow-sm p-8 border border-gray-200">
        <div className="text-center mb-8">
          <h1 className="text-2xl font-bold text-gray-900 mb-2">호스트 온보딩 · 주소 확인</h1>
          <p className="text-gray-600 text-sm">
            신청 ID <span className="font-mono">{application.id}</span> — 숙소 주소를 확인한 뒤
            번역·지도로 위치를 검증합니다.
          </p>
        </div>
        <div className="space-y-6">
          <div>
            <label htmlFor="ha-address" className="block text-sm font-medium text-gray-700 mb-2">
              주소 <span className="text-red-500">*</span>
            </label>
            <input
              id="ha-address"
              type="text"
              value={koreanAddress}
              onChange={(e) => setKoreanAddress(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div className="flex gap-3">
            <Link
              to={`/host-applications/${id}`}
              className="flex-1 py-3 text-center border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
            >
              취소
            </Link>
            <button
              type="button"
              onClick={() => void handleInputSubmit()}
              disabled={isLoading || !koreanAddress.trim()}
              className={`flex-1 py-3 rounded-lg text-white font-medium ${
                isLoading || !koreanAddress.trim()
                  ? 'bg-gray-400'
                  : 'bg-blue-600 hover:bg-blue-700'
              }`}
            >
              {isLoading ? '번역·지오코딩 중…' : '번역 및 지도 확인'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const renderMapStep = () => {
    if (!translationResult) return null;
    return (
      <div>
        <div className="text-center mb-8">
          <h1 className="text-2xl font-bold text-gray-900 mb-2">위치 확인</h1>
          <p className="text-gray-600 text-sm">지도에서 위치가 맞는지 확인해주세요.</p>
        </div>
        <MapComparison
          koreanAddress={koreanAddress}
          englishAddress={translationResult.englishAddress}
          lat={translationResult.lat}
          lng={translationResult.lng}
          onConfirm={handleLocationCorrect}
          onLocationDifferent={handleLocationIncorrect}
          isLoading={isLoading}
        />
        <div className="text-center mt-6">
          <button
            type="button"
            onClick={() => setCurrentStep('input')}
            disabled={isLoading}
            className="px-6 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
          >
            이전 단계
          </button>
        </div>
      </div>
    );
  };

  const renderCorrectionStep = () => {
    if (!translationResult) return null;
    return (
      <div>
        <div className="text-center mb-8">
          <h1 className="text-2xl font-bold text-gray-900 mb-2">주소 보정</h1>
          <p className="text-gray-600 text-sm">정확한 위치를 위해 주소를 다시 입력해주세요.</p>
        </div>
        <div className="max-w-2xl mx-auto mb-8">
          <div className="bg-white rounded-lg border border-gray-200 p-6 space-y-4">
            <div>
              <span className="text-sm text-gray-500">기존 주소</span>
              <div className="p-3 bg-gray-50 rounded-lg text-gray-700 text-sm mt-1">
                {koreanAddress}
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">새 주소</label>
              <textarea
                value={correctionAddress}
                onChange={(e) => setCorrectionAddress(e.target.value)}
                rows={3}
                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 resize-none"
              />
            </div>
          </div>
        </div>
        {correctionTranslationResult && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <div className="bg-white rounded-lg border border-gray-200 p-4">
                <NaverMapComponent
                  address={koreanAddress}
                  lat={translationResult.lat}
                  lng={translationResult.lng}
                />
              </div>
              <div className="bg-white rounded-lg border border-gray-200 p-4">
                <GoogleMapComponent
                  address={correctionTranslationResult.englishAddress}
                  lat={correctionTranslationResult.lat}
                  lng={correctionTranslationResult.lng}
                />
              </div>
            </div>
            <div className="flex gap-4 justify-center">
              <button
                type="button"
                onClick={handleAddressCorrectionConfirm}
                disabled={!correctionTranslationResult}
                className="px-8 py-3 rounded-lg bg-green-600 text-white font-medium hover:bg-green-700 disabled:bg-gray-400"
              >
                보정 주소로 계속
              </button>
              <button
                type="button"
                onClick={() => setCurrentStep('map')}
                className="px-8 py-3 rounded-lg border border-gray-300 text-gray-700 hover:bg-gray-50"
              >
                이전
              </button>
            </div>
          </div>
        )}
        {!correctionAddress.trim() && (
          <p className="text-center text-gray-500 text-sm py-8">새 주소를 입력해주세요.</p>
        )}
      </div>
    );
  };

  const renderStayFieldsStep = () => {
    const ft = finalTranslation();
    if (!ft) {
      return (
        <div className="text-center py-12 text-gray-600">
          번역 결과가 없습니다. 처음부터 다시 진행해주세요.
          <div className="mt-4">
            <button
              type="button"
              onClick={() => setCurrentStep('input')}
              className="text-blue-600 underline"
            >
              주소 입력으로
            </button>
          </div>
        </div>
      );
    }
    return (
      <div className="max-w-2xl mx-auto">
        <div className="bg-white rounded-lg shadow-sm p-8 border border-gray-200 space-y-6">
          <h1 className="text-2xl font-bold text-gray-900">스테이 정보·승인</h1>
          <p className="text-sm text-gray-600">
            영문 주소: <span className="font-medium text-gray-900">{ft.englishAddress}</span>
            {ft.englishDetailAddress?.trim() ? (
              <span className="block mt-1">상세: {ft.englishDetailAddress}</span>
            ) : null}
          </p>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              스테이 이름 <span className="text-red-500">*</span>
            </label>
            <input
              type="text"
              value={stayName}
              onChange={(e) => setStayName(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">비고 (선택)</label>
            <textarea
              value={stayNote}
              onChange={(e) => setStayNote(e.target.value)}
              rows={2}
              className="w-full p-3 border border-gray-300 rounded-lg resize-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              표시 정보 (display_info)
            </label>
            <p className="text-xs text-gray-500 mb-1">
              Stay 추가와 같이 기본은 위 영문 주소입니다. 필요 시 수정할 수 있습니다.
            </p>
            <input
              type="text"
              value={displayInfo}
              onChange={(e) => setDisplayInfo(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <label className="flex items-start gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={addressConfirmed}
              onChange={(e) => setAddressConfirmed(e.target.checked)}
              className="mt-1"
            />
            <span className="text-sm text-gray-800">
              지도에서 숙소 위치·주소를 확인했으며, 아래 내용으로 온보딩 승인(스테이 생성)을 진행합니다.
            </span>
          </label>
          <div className="flex gap-3">
            <button
              type="button"
              onClick={() => setCurrentStep(isCorrection ? 'address-correction' : 'map')}
              className="flex-1 py-3 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
              disabled={isLoading}
            >
              이전
            </button>
            <button
              type="button"
              onClick={() => void handleApproveSubmit()}
              disabled={isLoading}
              className="flex-1 py-3 rounded-lg bg-blue-600 text-white font-medium hover:bg-blue-700 disabled:bg-gray-400"
            >
              {isLoading ? '승인 처리 중…' : '승인(스테이 생성)'}
            </button>
          </div>
        </div>
      </div>
    );
  };

  const renderSuccessStep = () => (
    <div className="max-w-xl mx-auto bg-white rounded-lg border border-gray-200 p-8 text-center space-y-4">
      <h1 className="text-2xl font-bold text-green-700">처리 완료</h1>
      <p className="text-gray-700 text-sm">스테이가 생성되고 신청이 승인되었습니다.</p>
      {successData && (
        <div className="text-left text-sm space-y-2 bg-gray-50 p-4 rounded-lg font-mono break-all">
          <p>Host ID: {successData.hostId}</p>
          <p>Stay ID: {successData.linked_stay_id}</p>
        </div>
      )}
      <div className="flex flex-col gap-2 pt-4">
        <Link
          to="/host-applications"
          className="py-3 rounded-lg bg-blue-600 text-white font-medium hover:bg-blue-700"
        >
          목록으로
        </Link>
        {successData?.linked_stay_id && (
          <a
            href={`https://koreaorder.com/stays/${successData.linked_stay_id}`}
            target="_blank"
            rel="noopener noreferrer"
            className="py-3 rounded-lg border border-gray-300 text-gray-800 hover:bg-gray-50"
          >
            주문 페이지 열기
          </a>
        )}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-gray-50 py-8 px-4">
      <div className="max-w-4xl mx-auto mb-4">
        <Link
          to={`/host-applications/${id}`}
          className="text-sm text-blue-600 hover:underline"
        >
          ← 신청 상세
        </Link>
      </div>
      {currentStep === 'input' && renderInputStep()}
      {currentStep === 'map' && renderMapStep()}
      {currentStep === 'address-correction' && renderCorrectionStep()}
      {currentStep === 'stay-fields' && renderStayFieldsStep()}
      {currentStep === 'success' && renderSuccessStep()}
    </div>
  );
};

export default HostApplicationCompletePage;
