import React, { useState, useEffect, useMemo } from 'react';
import { HostSummaryResponse, HostFunnelData } from '../types';
import { getHostsSummary } from '../utils/hostApi';
import { transformHostSummaryList, formatDateShort, getStageColorClass, getGateColorClass } from '../utils/hostUtils';
import LoadingSpinner from '../components/LoadingSpinner';
import ErrorMessage from '../components/ErrorMessage';

type SortField = 'hostName' | 'stayName' | 'phone' | 'installationDate' | 'lastAccessDate' | 'lastOrderDate' | 'stage';
type SortDirection = 'asc' | 'desc';

const HostFunnelPage: React.FC = () => {
  const [hostData, setHostData] = useState<HostFunnelData[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [stageFilter, setStageFilter] = useState<string>('전체');
  const [showOnlyInstalledStays, setShowOnlyInstalledStays] = useState(true);
  const [sortField, setSortField] = useState<SortField>('installationDate');
  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');

  // API 호출
  const fetchHostData = async () => {
    try {
      setLoading(true);
      setError(null);
      
      const response: HostSummaryResponse = await getHostsSummary();
      const transformedData = transformHostSummaryList(response.data);
      setHostData(transformedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : '호스트 정보를 불러오는데 실패했습니다.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchHostData();
  }, []);

  // 필터링 및 정렬된 데이터
  const filteredAndSortedData = useMemo(() => {
    let filtered = hostData;

    // 검색 필터
    if (searchTerm) {
      filtered = filtered.filter(host => 
        (host.hostName && host.hostName.toLowerCase().includes(searchTerm.toLowerCase())) ||
        (host.stayName && host.stayName.toLowerCase().includes(searchTerm.toLowerCase())) ||
        (host.phone && host.phone.includes(searchTerm))
      );
    }

    // 상태 필터
    if (stageFilter !== '전체') {
      filtered = filtered.filter(host => host.stage === stageFilter);
    }

    // 설치일 필터
    if (showOnlyInstalledStays) {
      filtered = filtered.filter(host => host.installationDate !== null);
    }

    // 정렬
    filtered.sort((a, b) => {
      let aValue: any = a[sortField];
      let bValue: any = b[sortField];

      // null 값 처리
      if (aValue === null && bValue === null) return 0;
      if (aValue === null) return sortDirection === 'asc' ? 1 : -1;
      if (bValue === null) return sortDirection === 'asc' ? -1 : 1;

      // 문자열 비교
      if (typeof aValue === 'string' && typeof bValue === 'string') {
        return sortDirection === 'asc' 
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue);
      }

      // 기본 비교
      if (aValue < bValue) return sortDirection === 'asc' ? -1 : 1;
      if (aValue > bValue) return sortDirection === 'asc' ? 1 : -1;
      return 0;
    });

    return filtered;
  }, [hostData, searchTerm, stageFilter, showOnlyInstalledStays, sortField, sortDirection]);

  // 상태별 통계
  const statistics = useMemo(() => {
    // 필터링된 데이터를 기준으로 통계 계산
    let dataForStats = hostData;
    
    // 설치일 필터 적용
    if (showOnlyInstalledStays) {
      dataForStats = dataForStats.filter(host => host.installationDate !== null);
    }

    const stats = {
      전체: dataForStats.length,
      '설치 → 접속': 0,
      '접속 → 첫 주문': 0,
      활성화: 0,
      '점검 요망 (20일 초과)': 0,
      공란: 0
    };

    dataForStats.forEach(host => {
      if (host.stage === '') {
        stats.공란++;
      } else {
        stats[host.stage as keyof typeof stats]++;
      }
    });

    return stats;
  }, [hostData, showOnlyInstalledStays]);

  // 정렬 핸들러
  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortDirection('desc');
    }
  };

  // 재시도 핸들러
  const handleRetry = () => {
    fetchHostData();
  };

  // 정렬 아이콘 렌더링
  const renderSortIcon = (field: SortField) => {
    if (sortField !== field) {
      return <span className="text-gray-400 ml-1">↕</span>;
    }
    return (
      <span className="text-blue-600 ml-1">
        {sortDirection === 'asc' ? '↑' : '↓'}
      </span>
    );
  };

  return (
    <>
      {loading && <LoadingSpinner />}
      
      {error && (
        <ErrorMessage 
          message={error} 
          onRetry={handleRetry}
        />
      )}
      
      {!loading && !error && (
        <div className="w-full space-y-6">
          {/* 페이지 헤더 */}
          <div className="bg-white rounded-lg shadow-sm p-6">
            <h1 className="text-2xl font-bold text-gray-900 mb-4">호스트 퍼널</h1>
            
            {/* 통계 */}
            <div className="grid grid-cols-2 md:grid-cols-6 gap-4 mb-6">
              {Object.entries(statistics).map(([key, count]) => (
                <div key={key} className="text-center">
                  <div className="text-2xl font-bold text-gray-900">{count}</div>
                  <div className="text-sm text-gray-600">{key}</div>
                </div>
              ))}
            </div>

            {/* 필터 및 검색 */}
            <div className="flex flex-col md:flex-row gap-4">
              {/* 검색 */}
              <div className="flex-1">
                <input
                  type="text"
                  placeholder="호스트명, 전화번호 또는 숙소명 검색..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
              </div>
              
              {/* 상태 필터 */}
              <select
                value={stageFilter}
                onChange={(e) => setStageFilter(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                <option value="전체">전체 상태</option>
                <option value="설치 → 접속">설치 → 접속</option>
                <option value="접속 → 첫 주문">접속 → 첫 주문</option>
                <option value="활성화">활성화</option>
                <option value="점검 요망 (20일 초과)">점검 요망 (20일 초과)</option>
                <option value="">공란</option>
              </select>
              
              {/* 설치일 필터 */}
              <select
                value={showOnlyInstalledStays ? "installed" : "all"}
                onChange={(e) => setShowOnlyInstalledStays(e.target.value === "installed")}
                className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                <option value="installed">설치된 스테이만 표시</option>
                <option value="all">모든 스테이 표시</option>
              </select>
            </div>
          </div>

          {/* 테이블 */}
          <div className="bg-white rounded-lg shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th 
                      className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                      onClick={() => handleSort('hostName')}
                    >
                      호스트명 {renderSortIcon('hostName')}
                    </th>
                    <th 
                      className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                      onClick={() => handleSort('phone')}
                    >
                      전화번호 {renderSortIcon('phone')}
                    </th>
                    <th 
                      className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                      onClick={() => handleSort('stayName')}
                    >
                      숙소 주소 {renderSortIcon('stayName')}
                    </th>
                    <th 
                      className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                      onClick={() => handleSort('installationDate')}
                    >
                      설치일 {renderSortIcon('installationDate')}
                    </th>
                    <th 
                      className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                      onClick={() => handleSort('lastAccessDate')}
                    >
                      최근 접속일 {renderSortIcon('lastAccessDate')}
                    </th>
                    <th 
                      className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                      onClick={() => handleSort('lastOrderDate')}
                    >
                      최근 주문일 {renderSortIcon('lastOrderDate')}
                    </th>
                    <th 
                      className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                      onClick={() => handleSort('stage')}
                    >
                      상태(Stage) {renderSortIcon('stage')}
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      액션 내용
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      비고
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {filteredAndSortedData.map((host, index) => (
                    <tr key={`${host.hostName}-${host.stayName}-${index}`} className="hover:bg-gray-50">
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                        {host.hostName}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {host.phone || '-'}
                      </td>
                      <td className="px-6 py-4 text-sm text-gray-900 max-w-xs truncate" title={host.stayName}>
                        {host.stayName}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {formatDateShort(host.installationDate)}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {formatDateShort(host.lastAccessDate)}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {formatDateShort(host.lastOrderDate)}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${getStageColorClass(host.stage)}`}>
                          {host.stage || '-'}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-sm text-gray-900 max-w-xs">
                        <div className="truncate" title={host.gateInfo.action}>
                          {host.gateInfo.gate && (
                            <span className={`font-semibold ${getGateColorClass(host.gateInfo.gate)}`}>
                              {host.gateInfo.gate}:
                            </span>
                          )}{' '}
                          {host.gateInfo.action}
                        </div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">
                        -
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* 데이터가 없는 경우 */}
            {filteredAndSortedData.length === 0 && (
              <div className="text-center py-12">
                <p className="text-gray-600">
                  {searchTerm || stageFilter !== '전체' || !showOnlyInstalledStays
                    ? '검색 조건에 맞는 호스트가 없습니다.' 
                    : '등록된 호스트가 없습니다.'}
                </p>
              </div>
            )}
          </div>

          {/* 결과 요약 */}
          {filteredAndSortedData.length > 0 && (
            <div className="bg-white rounded-lg shadow-sm p-4">
              <p className="text-sm text-gray-600">
                총 {hostData.length}개 중 {filteredAndSortedData.length}개 표시
                {searchTerm && ` (검색: "${searchTerm}")`}
                {stageFilter !== '전체' && ` (필터: ${stageFilter})`}
                {!showOnlyInstalledStays && ` (모든 스테이 포함)`}
              </p>
            </div>
          )}
        </div>
      )}
    </>
  );
};

export default HostFunnelPage;
