import React from 'react';
import { ManualCategory, Manual } from '../types';
import ManualList from './ManualList';

interface ManualCategoryAccordionProps {
  category: ManualCategory;
  manuals: Manual[];
  isExpanded: boolean;
  isAdmin?: boolean;
  onToggle: (categoryId: string) => void;
  onManualClick?: (manual: Manual) => void;
  onManualEdit?: (manual: Manual) => void;
  onManualDelete?: (manual: Manual) => void;
  onReorder?: () => void;
}

const ManualCategoryAccordion: React.FC<ManualCategoryAccordionProps> = ({
  category,
  manuals,
  isExpanded,
  isAdmin = false,
  onToggle,
  onManualClick,
  onManualEdit,
  onManualDelete,
  onReorder,
}) => {
  const handleToggle = () => {
    onToggle(category.id);
  };

  const categoryManuals = manuals.filter(
    (manual) => manual.categoryId === category.id && manual.isActive
  );

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200 mb-4">
      {/* 카테고리 헤더 */}
      <button
        onClick={handleToggle}
        className="w-full px-6 py-4 flex items-center justify-between hover:bg-gray-50 transition-colors"
      >
        <div className="flex items-center gap-3">
          <span className="text-lg font-semibold text-gray-900">
            {category.name}
          </span>
          <span className="text-sm text-gray-500">
            ({categoryManuals.length}개)
          </span>
        </div>
        <svg
          className={`w-5 h-5 text-gray-500 transition-transform ${
            isExpanded ? 'transform rotate-180' : ''
          }`}
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M19 9l-7 7-7-7"
          />
        </svg>
      </button>

      {/* 카테고리 내용 (메뉴얼 목록) */}
      {isExpanded && (
        <div className="px-6 pb-4">
          {categoryManuals.length > 0 ? (
            <ManualList
              manuals={categoryManuals}
              isAdmin={isAdmin}
              onManualClick={onManualClick}
              onManualEdit={onManualEdit}
              onManualDelete={onManualDelete}
              onReorder={onReorder}
            />
          ) : (
            <div className="text-center py-8 text-gray-500">
              메뉴얼이 없습니다.
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default ManualCategoryAccordion;
