import React, { useState } from 'react';
import { Order } from '../types';
import { updateSettlementPrice } from '../utils/orderUpdateApi';
import { useToast } from '../hooks/useToast';

interface SettlementPriceEditorProps {
  order: Order;
  onUpdate: (orderId: string, updatedOrder: Order) => void;
  isReadOnly?: boolean; // 읽기 전용 모드 (DELIVERY_COMPLETED 상태일 때)
}

const SettlementPriceEditor: React.FC<SettlementPriceEditorProps> = ({ order, onUpdate, isReadOnly = false }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [inputValue, setInputValue] = useState('');
  const [isUpdating, setIsUpdating] = useState(false);
  const { showToast } = useToast();

  // 원 주문 금액 계산
  const originalAmount = order.items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  
  // 정산 금액 (없으면 원 주문 금액 사용)
  const currentSettlementPrice = order.settlementPrice ?? originalAmount;
  
  // 정산 금액이 수정되었는지 확인
  const isModified = currentSettlementPrice !== originalAmount;

  // 입력값 유효성 검사
  const parsedInput = parseInt(inputValue.replace(/,/g, ''));
  const isValidInput = !isNaN(parsedInput) && parsedInput >= 0 && parsedInput <= originalAmount;

  // 입력 핸들러 (숫자만 입력, 천 단위 콤마)
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value.replace(/,/g, '');
    if (value === '' || /^\d+$/.test(value)) {
      setInputValue(value ? parseInt(value).toLocaleString() : '');
    }
  };

  // 저장 핸들러
  const handleSave = async () => {
    if (!isValidInput) return;

    setIsUpdating(true);
    try {
      await updateSettlementPrice(order.orderId, parsedInput);
      
      // 성공 시 로컬 상태 업데이트
      const updatedOrder = {
        ...order,
        settlementPrice: parsedInput
      };
      
      onUpdate(order.orderId, updatedOrder);
      showToast('정산 금액이 저장되었습니다', 'success');
      
      // 아코디언 접기 및 입력값 초기화
      setIsExpanded(false);
      setInputValue('');
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '저장에 실패했습니다. 다시 시도해주세요',
        'error'
      );
    } finally {
      setIsUpdating(false);
    }
  };

  // 취소 핸들러
  const handleCancel = () => {
    setInputValue('');
    setIsExpanded(false);
  };

  return (
    <div className="border-t border-gray-200 pt-4 mt-4">
      {/* 아코디언 헤더 */}
      <div className="flex items-center gap-2">
        <button
          onClick={() => setIsExpanded(!isExpanded)}
          className="flex items-center justify-between flex-1 text-left hover:bg-gray-50 rounded p-2 transition-colors duration-200"
        >
          <div className="flex items-center gap-2">
            <h3 className="text-md font-medium text-gray-900">💰 정산 금액</h3>
            {isModified ? (
              <span className="text-sm text-blue-600 font-semibold">
                {currentSettlementPrice.toLocaleString()}원 (수정됨)
              </span>
            ) : (
              <span className="text-sm text-gray-500">
                {currentSettlementPrice.toLocaleString()}원
              </span>
            )}
          </div>
          <svg
            className={`w-5 h-5 text-gray-500 transform transition-transform duration-200 ${
              isExpanded ? 'rotate-180' : ''
            }`}
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
          </svg>
        </button>
      </div>

      {/* 아코디언 콘텐츠 */}
      {isExpanded && (
        <div className="mt-3 animate-fade-in">
          <div className="bg-gray-50 rounded-lg p-4 space-y-4">
            {/* 주문 정보 */}
            <div className="space-y-2">
              <div className="flex justify-between items-center">
                <span className="text-sm text-gray-600">원 주문 금액</span>
                <span className="text-sm font-medium text-gray-900">
                  {originalAmount.toLocaleString()}원
                </span>
              </div>

              {isModified && (
                <>
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-600">실제 결제 금액</span>
                    <span className="text-sm font-semibold text-blue-600">
                      {currentSettlementPrice.toLocaleString()}원
                    </span>
                  </div>
                </>
              )}
            </div>

            {/* 읽기 전용 모드일 때는 입력 섹션과 버튼 숨김 */}
            {!isReadOnly && (
              <>
                {/* 구분선 */}
                <div className="border-t border-gray-200"></div>

                {/* 입력 섹션 */}
                <div className="space-y-3">
                  <h4 className="text-sm font-medium text-gray-900">💰 결제 금액 수정</h4>
                  
                  <div>
                    <label className="block text-sm text-gray-700 mb-2">
                      새 결제 금액 입력
                    </label>
                    <div className="flex items-center gap-2">
                      <input
                        type="text"
                        value={inputValue}
                        onChange={handleInputChange}
                        placeholder="예: 50000"
                        disabled={isUpdating}
                        className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent disabled:bg-gray-100 disabled:cursor-not-allowed"
                      />
                      <span className="text-sm text-gray-600">원</span>
                    </div>
                    
                    {/* 유효성 검사 메시지 */}
                    {inputValue && !isValidInput && (
                      <p className="mt-1 text-sm text-red-600">
                        {parsedInput > originalAmount 
                          ? '원 주문 금액 이하만 입력 가능합니다'
                          : '올바른 금액을 입력해주세요'}
                      </p>
                    )}
                  </div>

                  {/* 주의사항 */}
                  <div className="bg-orange-50 border border-orange-200 rounded-md p-3">
                    <p className="text-xs text-orange-800">
                      ⚠️ <strong>주의사항</strong>
                    </p>
                    <ul className="text-xs text-orange-700 mt-1 space-y-1 ml-4 list-disc">
                      <li>원 주문 금액 이하만 입력 가능합니다</li>
                    </ul>
                  </div>
                </div>

                {/* 버튼 */}
                <div className="flex justify-end gap-2 pt-2">
                  <button
                    onClick={handleCancel}
                    disabled={isUpdating}
                    className="px-4 py-2 bg-gray-300 hover:bg-gray-400 text-gray-700 font-medium rounded-md transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    취소
                  </button>
                  <button
                    onClick={handleSave}
                    disabled={!isValidInput || isUpdating}
                    className="px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 text-white font-medium rounded-md transition-colors duration-200 flex items-center disabled:cursor-not-allowed"
                  >
                    {isUpdating ? (
                      <>
                        <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        저장 중...
                      </>
                    ) : (
                      '저장'
                    )}
                  </button>
                </div>
              </>
            )}

            {/* 읽기 전용 안내 */}
            {isReadOnly && (
              <div className="mt-2 text-xs text-gray-500 italic">
                확인용 (수정 불가)
              </div>
            )}
          </div>
        </div>
      )}

    </div>
  );
};

export default SettlementPriceEditor;

