import React, { useCallback, useEffect, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import {
  AdminResponse,
  HOST_APPLICATION_CODES,
  HostApplicationQrStatus,
  StateConflictBody,
} from '../types/hostApplication';
import {
  HostApplicationApiError,
  getHostApplication,
  patchHostApplicationQrStatus,
  rejectHostApplication,
} from '../utils/hostApplicationApi';
import { useToast } from '../hooks/useToast';
import {
  labelHostApplicationQrStatus,
  labelHostApplicationStatus,
} from '../utils/hostApplicationLabels';

const HostApplicationDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { showToast } = useToast();
  const [row, setRow] = useState<AdminResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [rejectOpen, setRejectOpen] = useState(false);
  const [rejectReason, setRejectReason] = useState('');
  const [rejectSubmitting, setRejectSubmitting] = useState(false);
  const [qrSubmitting, setQrSubmitting] = useState(false);
  const [qrTarget, setQrTarget] = useState<HostApplicationQrStatus | ''>('');

  const load = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    try {
      const data = await getHostApplication(id);
      setRow(data);
    } catch (e) {
      const msg =
        e instanceof HostApplicationApiError
          ? e.message
          : e instanceof Error
            ? e.message
            : '불러오지 못했습니다.';
      showToast(msg, 'error');
      setRow(null);
    } finally {
      setLoading(false);
    }
  }, [id, showToast]);

  useEffect(() => {
    void load();
  }, [load]);

  const handleReject = async () => {
    if (!id || !rejectReason.trim()) {
      showToast('반려 사유를 입력해주세요.', 'error');
      return;
    }
    setRejectSubmitting(true);
    try {
      await rejectHostApplication(id, rejectReason.trim());
      showToast('반려 처리되었습니다.', 'success');
      setRejectOpen(false);
      navigate('/host-applications');
    } catch (e) {
      if (e instanceof HostApplicationApiError) {
        if (e.code === HOST_APPLICATION_CODES.ALREADY_APPROVED) {
          showToast('이미 승인된 신청입니다.', 'error');
        } else if (e.code === HOST_APPLICATION_CODES.ALREADY_REJECTED) {
          showToast('이미 반려된 신청입니다.', 'error');
        } else {
          showToast(e.message, 'error');
        }
      } else {
        showToast('반려 처리에 실패했습니다.', 'error');
      }
    } finally {
      setRejectSubmitting(false);
    }
  };

  if (!id) {
    return (
      <div className="p-8 text-center text-gray-600">잘못된 경로입니다.</div>
    );
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center text-gray-500">
        불러오는 중…
      </div>
    );
  }

  if (!row) {
    return (
      <div className="min-h-screen bg-gray-50 p-8 text-center">
        <p className="text-gray-600 mb-4">신청을 찾을 수 없습니다.</p>
        <Link to="/host-applications" className="text-blue-600 hover:underline">
          목록으로
        </Link>
      </div>
    );
  }

  const canOnboard = row.status === 'PENDING' || row.status === 'REJECTED';
  const canReject = row.status === 'PENDING';
  const hasLinkedStay = Boolean(row.linked_stay_id || row.linked_stay);
  const isLegacyApprovedNoStay =
    row.status === 'APPROVED' && !row.linked_stay_id && !row.linked_stay;
  const effectiveQrStatus: HostApplicationQrStatus | undefined =
    row.qr_status ??
    (row.status === 'APPROVED' && hasLinkedStay ? 'NOT_STARTED' : undefined);
  const qrNextOptions: HostApplicationQrStatus[] =
    effectiveQrStatus === 'NOT_STARTED'
      ? ['QR_GENERATED']
      : effectiveQrStatus === 'QR_GENERATED'
        ? ['QR_SENT']
        : [];

  const conflictQrHint = (e: HostApplicationApiError): string => {
    const raw = e.rawBody;
    if (raw && typeof raw === 'object' && 'data' in raw) {
      const d = (raw as { data?: unknown }).data;
      if (d && typeof d === 'object' && 'current_qr_status' in d) {
        const c = (d as StateConflictBody).current_qr_status;
        if (c) return ` (현재 QR: ${labelHostApplicationQrStatus(c)})`;
      }
    }
    return '';
  };

  const handleQrPatch = async () => {
    if (!id || !qrTarget) {
      showToast('변경할 QR 상태를 선택해주세요.', 'error');
      return;
    }
    setQrSubmitting(true);
    try {
      const updated = await patchHostApplicationQrStatus(id, qrTarget);
      setRow(updated);
      setQrTarget('');
      showToast('QR 상태가 반영되었습니다.', 'success');
    } catch (e) {
      if (e instanceof HostApplicationApiError) {
        if (e.code === HOST_APPLICATION_CODES.NOT_APPROVED) {
          showToast('승인된 신청만 QR 상태를 변경할 수 있습니다.', 'error');
        } else if (e.code === HOST_APPLICATION_CODES.QR_REQUIRES_LINKED_STAY) {
          showToast('연결된 스테이가 있어야 QR 상태를 변경할 수 있습니다.', 'error');
        } else if (e.code === HOST_APPLICATION_CODES.QR_INVALID_TRANSITION) {
          showToast(`허용되지 않는 QR 상태 전환입니다.${conflictQrHint(e)}`, 'error');
        } else if (e.status === 409) {
          showToast(`${e.message}${conflictQrHint(e)}`, 'error');
        } else {
          showToast(e.message, 'error');
        }
      } else {
        showToast('QR 상태 변경에 실패했습니다.', 'error');
      }
    } finally {
      setQrSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 py-8 px-4">
      <div className="max-w-3xl mx-auto space-y-6">
        <div className="flex flex-wrap items-center gap-3">
          <Link
            to="/host-applications"
            className="text-sm text-blue-600 hover:underline"
          >
            ← 목록
          </Link>
          <span
            className={`text-xs font-semibold px-2 py-1 rounded ${
              row.status === 'PENDING'
                ? 'bg-amber-100 text-amber-800'
                : row.status === 'REJECTED'
                  ? 'bg-red-100 text-red-800'
                  : 'bg-green-100 text-green-800'
            }`}
          >
            {labelHostApplicationStatus(row.status)}
          </span>
        </div>

        <h1 className="text-2xl font-bold text-gray-900">신청 상세 · {row.id}</h1>

        {row.status === 'REJECTED' && row.rejectionReason && (
          <div className="p-4 bg-red-50 border border-red-200 rounded-lg text-sm">
            <p className="font-medium text-red-900">반려 사유</p>
            <p className="text-red-800 mt-1 whitespace-pre-wrap">{row.rejectionReason}</p>
            {row.rejectedAt && (
              <p className="text-red-700 mt-2 text-xs">{row.rejectedAt}</p>
            )}
          </div>
        )}

        {canOnboard && (
          <div className="p-4 bg-blue-50 border border-blue-200 rounded-lg text-sm text-blue-900">
            온보딩 승인 시 스테이가 생성되고 신청이 승인됩니다. 반려 건을 승인하면 반려 정보가
            초기화됩니다.
          </div>
        )}

        <section className="bg-white rounded-lg border border-gray-200 shadow-sm p-6 space-y-4">
          <h2 className="text-lg font-semibold text-gray-900">신청자·숙소</h2>
          <dl className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-sm">
            <div>
              <dt className="text-gray-500">이름</dt>
              <dd className="font-medium text-gray-900">{row.name}</dd>
            </div>
            <div>
              <dt className="text-gray-500">전화</dt>
              <dd className="font-medium text-gray-900">{row.phone}</dd>
            </div>
            <div className="sm:col-span-2">
              <dt className="text-gray-500">숙소 주소</dt>
              <dd className="font-medium text-gray-900">{row.address}</dd>
            </div>
            <div className="sm:col-span-2">
              <dt className="text-gray-500">공동현관 비밀번호</dt>
              <dd className="font-medium text-gray-900">{row.entrancePassword}</dd>
            </div>
          </dl>
        </section>

        <section className="bg-white rounded-lg border border-gray-200 shadow-sm p-6 space-y-4">
          <h2 className="text-lg font-semibold text-gray-900">수령·배송</h2>
          <dl className="text-sm space-y-2">
            <div>
              <dt className="text-gray-500">수령 방법</dt>
              <dd className="font-medium text-gray-900">{row.receiveMethod}</dd>
            </div>
            {row.receiveAddressChange && (
              <div>
                <dt className="text-gray-500">수령 주소 변경</dt>
                <dd className="font-medium text-gray-900">{row.receiveAddressChange}</dd>
              </div>
            )}
          </dl>
        </section>

        <section className="bg-white rounded-lg border border-gray-200 shadow-sm p-6 space-y-4">
          <h2 className="text-lg font-semibold text-gray-900">사업·운영</h2>
          <dl className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-sm">
            <div>
              <dt className="text-gray-500">사업자 유형</dt>
              <dd className="font-medium text-gray-900">{row.businessType}</dd>
            </div>
            <div>
              <dt className="text-gray-500">운영 상태</dt>
              <dd className="font-medium text-gray-900">{row.operationStatus}</dd>
            </div>
            <div className="sm:col-span-2">
              <dt className="text-gray-500">운영 형태</dt>
              <dd className="font-medium text-gray-900">
                {row.operationType?.length ? row.operationType.join(', ') : '—'}
              </dd>
            </div>
            <div className="sm:col-span-2">
              <dt className="text-gray-500">인지 경로</dt>
              <dd className="font-medium text-gray-900">
                {row.referralSource?.length ? row.referralSource.join(', ') : '—'}
              </dd>
            </div>
            {row.referrerName && (
              <div className="sm:col-span-2">
                <dt className="text-gray-500">추천인 등</dt>
                <dd className="font-medium text-gray-900">{row.referrerName}</dd>
              </div>
            )}
            <div>
              <dt className="text-gray-500">택배 안내 동의</dt>
              <dd className="font-medium text-gray-900">{row.shippingConfirm ? '예' : '아니오'}</dd>
            </div>
          </dl>
        </section>

        {row.status === 'APPROVED' && (
          <section className="bg-white rounded-lg border border-gray-200 shadow-sm p-6 space-y-2 text-sm">
            <h2 className="text-lg font-semibold text-gray-900">승인 정보</h2>
            {isLegacyApprovedNoStay && (
              <p className="text-amber-800 bg-amber-50 border border-amber-200 rounded-lg p-3 text-sm">
                레거시 데이터: 승인되었으나 연결 스테이 ID가 없습니다. QR·포스터 연동 전 백엔드에서 스테이
                연결이 필요할 수 있습니다.
              </p>
            )}
            <p>
              <span className="text-gray-500">Host ID:</span>{' '}
              <span className="font-mono">{row.hostId ?? '—'}</span>
            </p>
            <p>
              <span className="text-gray-500">Stay ID:</span>{' '}
              <span className="font-mono">{row.linked_stay_id ?? row.linked_stay?.stay_id ?? '—'}</span>
            </p>
            {row.linked_stay && (
              <dl className="grid grid-cols-1 gap-2 pt-2 border-t border-gray-100">
                <div>
                  <dt className="text-gray-500">연결 스테이 이름</dt>
                  <dd className="font-medium text-gray-900">{row.linked_stay.stay_name}</dd>
                </div>
                <div>
                  <dt className="text-gray-500">표시 한 줄</dt>
                  <dd className="font-medium text-gray-900">{row.linked_stay.display_line}</dd>
                </div>
              </dl>
            )}
            <p>
              <span className="text-gray-500">QR 상태:</span>{' '}
              <span className="font-medium">
                {effectiveQrStatus != null
                  ? labelHostApplicationQrStatus(effectiveQrStatus)
                  : '—'}
              </span>
            </p>
            <p className="flex flex-wrap items-center gap-2">
              <span className="text-gray-500">중복여부:</span>
              {row.duplicate_stay_name === true ? (
                <span
                  className="inline-flex items-center gap-1.5 rounded-md border border-amber-400 bg-amber-100 px-2.5 py-1 text-sm font-bold text-amber-950 shadow-sm"
                  title="동일 이름의 활성 스테이가 둘 이상 집계된 경우입니다"
                >
                  <svg
                    className="h-4 w-4 shrink-0 text-amber-800"
                    viewBox="0 0 20 20"
                    fill="currentColor"
                    aria-hidden
                  >
                    <path
                      fillRule="evenodd"
                      d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z"
                      clipRule="evenodd"
                    />
                  </svg>
                  중복
                </span>
              ) : row.duplicate_stay_name === false ? (
                <span className="font-medium text-gray-700">아니오</span>
              ) : (
                <span className="font-medium text-gray-400">—</span>
              )}
            </p>
            {row.duplicate_stay_name === true && (
              <p className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-sm text-amber-950">
                스캔·안내 시 동일 표기 스테이와 혼동되지 않도록 확인해 주세요.
              </p>
            )}
            {row.approvedAt && (
              <p className="text-gray-600 text-xs">승인 시각: {row.approvedAt}</p>
            )}
          </section>
        )}

        {row.status === 'APPROVED' && hasLinkedStay && (
          <section className="bg-white rounded-lg border border-gray-200 shadow-sm p-6 space-y-4 text-sm">
            <h2 className="text-lg font-semibold text-gray-900">QR 상태 변경</h2>
            <p className="text-gray-600">
              제작 전 → QR 제작 → QR 발송 순으로만 변경할 수 있습니다. 동일 값으로 다시 요청하면 성공(멱등)으로
              처리될 수 있습니다.
            </p>
            {qrNextOptions.length === 0 ? (
              <p className="text-gray-500">현재 단계에서 더 진행할 QR 전환이 없습니다.</p>
            ) : (
              <div className="flex flex-wrap items-end gap-3">
                <label className="flex flex-col gap-1 text-gray-700">
                  <span className="text-xs text-gray-500">다음 상태</span>
                  <select
                    value={qrTarget}
                    onChange={(e) =>
                      setQrTarget((e.target.value || '') as HostApplicationQrStatus | '')
                    }
                    className="border border-gray-300 rounded-lg px-3 py-2 text-sm bg-white min-w-[200px]"
                  >
                    <option value="">선택</option>
                    {qrNextOptions.map((opt) => (
                      <option key={opt} value={opt}>
                        {labelHostApplicationQrStatus(opt)}
                      </option>
                    ))}
                  </select>
                </label>
                <button
                  type="button"
                  onClick={() => void handleQrPatch()}
                  disabled={qrSubmitting || !qrTarget}
                  className="px-4 py-2 rounded-lg bg-blue-600 text-white font-medium hover:bg-blue-700 disabled:opacity-50"
                >
                  {qrSubmitting ? '처리 중…' : '적용'}
                </button>
              </div>
            )}
          </section>
        )}

        <div className="flex flex-wrap gap-3">
          {canOnboard && (
            <Link
              to={`/host-applications/${row.id}/complete`}
              className="inline-flex items-center justify-center px-5 py-2.5 rounded-lg bg-blue-600 text-white font-medium hover:bg-blue-700"
            >
              스테이 등록·온보딩 승인
            </Link>
          )}
          {canReject && (
            <button
              type="button"
              onClick={() => setRejectOpen(true)}
              className="inline-flex items-center justify-center px-5 py-2.5 rounded-lg border border-red-300 text-red-700 font-medium hover:bg-red-50"
            >
              반려
            </button>
          )}
        </div>
      </div>

      {rejectOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40">
          <div className="bg-white rounded-lg shadow-xl max-w-md w-full p-6 space-y-4">
            <h3 className="text-lg font-semibold text-gray-900">반려 사유</h3>
            <textarea
              value={rejectReason}
              onChange={(e) => setRejectReason(e.target.value)}
              rows={4}
              className="w-full border border-gray-300 rounded-lg p-3 text-sm resize-none focus:ring-2 focus:ring-blue-500"
              placeholder="내부 메모로 사유를 입력해주세요."
            />
            <div className="flex justify-end gap-2">
              <button
                type="button"
                onClick={() => setRejectOpen(false)}
                className="px-4 py-2 text-sm border border-gray-300 rounded-lg hover:bg-gray-50"
                disabled={rejectSubmitting}
              >
                취소
              </button>
              <button
                type="button"
                onClick={() => void handleReject()}
                disabled={rejectSubmitting}
                className="px-4 py-2 text-sm rounded-lg bg-red-600 text-white hover:bg-red-700 disabled:opacity-50"
              >
                {rejectSubmitting ? '처리 중…' : '반려하기'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HostApplicationDetailPage;
